/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.html5;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.util.EmptyUtil;import page2020.view.Content;import page2020.view.Element;public class H5form extends Element<H5form, Content<?>> {	public static final class Attr {		public static final String acceptCharset = "accept-charset";		public static final String action = "action";		public static final String autoComplete = "autocomplete";		public static final String encType = "enctype";		public static final String method = "method";		public static final String name = "name";		public static final String noValidate = "novalidate";		public static final String rel = "rel";		public static final String target = "target";	}	public static final class ValueOfRel {		public static final String external = "external";		public static final String help = "help";		public static final String license = "license";		public static final String next = "next";		public static final String noFollow = "nofollow";		public static final String noOpener = "noopener";		public static final String noReferrer = "noreferrer";		public static final String opener = "opener";		public static final String prev = "prev";				public static final String search = "search";			}	private static Logger log = LoggerFactory.getLogger(H5form.class);	public H5form() {		super("form");	}	public H5form acceptCharset(String acceptCharset) {		if (EmptyUtil.not(acceptCharset)) {			super.getAttrMap().put(Attr.acceptCharset, acceptCharset.trim());			return null;		} else {			log.error("acceptCharset: argument(acceptCharset) is empty !");		}		return this;	}	public H5form action(String path) {		if (EmptyUtil.not(path)) {			super.getAttrMap().put(Attr.action, path.trim());		} else {			log.error("action: argument(path) is empty !");		}		return this;	}	public H5form autoComplete(boolean autoComplete) {		if (autoComplete) {			super.getAttrMap().put(Attr.autoComplete, "on");		} else {			super.getAttrMap().put(Attr.autoComplete, "off");		}		return this;	}	public H5form encType(String encType) {		if (EmptyUtil.not(encType)) {			super.getAttrMap().put(Attr.encType, encType.trim());		} else {			log.error("encType: argument(encType) is empty !");		}		return this;	}	public H5form method(String methodType) {		if (EmptyUtil.not(methodType)) {			super.getAttrMap().put(Attr.method, methodType.trim());		} else {			log.error("method: argument(methodType) is empty !");		}		return this;	}	public H5form h5Name(String h5name) {		if (EmptyUtil.not(h5name)) {			super.getAttrMap().put(Attr.name, h5name.trim());		} else {			log.error("h5Name: argument(h5name) is empty !");		}		return this;	}	public H5form noValidate(boolean noValidate) {		if (noValidate) {			super.getAttrSet().add(Attr.noValidate);		} else {			super.getAttrSet().remove(Attr.noValidate);		}		return this;	}	public H5form rel(String relType) {		if (EmptyUtil.not(relType)) {			super.getAttrMap().put(Attr.rel, relType.trim());		} else {			log.error("rel: argument(relType) is empty !");		}		return this;	}	public H5form target(String targetType) {		if (EmptyUtil.not(targetType)) {			super.getAttrMap().put(Attr.target, targetType.trim());		} else {			log.error("target: argument(targetType) is empty !");		}			return this;	}	@Override	protected boolean isAttr(String attrName) {		switch (super.attrName(attrName)) {		case Attr.acceptCharset:		case Attr.action:		case Attr.autoComplete:		case Attr.encType:		case Attr.method:		case Attr.name:		case Attr.noValidate:		case Attr.rel:		case Attr.target:				return true;		default:			return super.isAttr(attrName);		}	}}